        return { kind: "default" };
    if (!value.startsWith(microphoneIdPrefix)) {
        return value.trim() ? { kind: "legacy", nativeId: value } : undefined;
    }
    const separator = value.indexOf(":", microphoneIdPrefix.length);
    if (separator < 0)
        return undefined;
    const backend = value.slice(microphoneIdPrefix.length, separator);
    const encodedNativeId = value.slice(separator + 1);
    if (!microphoneBackends.has(backend) ||
        !encodedNativeId ||
        !/^[A-Za-z0-9_-]+$/.test(encodedNativeId))
        return undefined;
    const nativeId = Buffer.from(encodedNativeId, "base64url").toString("utf8");
    if (Buffer.from(nativeId, "utf8").toString("base64url") !== encodedNativeId ||
        !isSafeNativeId(nativeId))
        return undefined;
