const isSafeNativeId = (value) => Boolean(value.trim()) &&
    value.length <= maximumNativeIdLength &&
    !hasUnsafeIdentifierCharacters(value);
const hasUnsafeIdentifierCharacters = (value) => [...value].some((character) => {
    const code = character.charCodeAt(0);
    return code < 32 || code === 127;
