    voiceLog("info", "auth.connectCloudCredential", "connect_start", {
        providerId,
    });
    const authId = authIdForCloudProvider(providerId);
    const existing = await store.read(authId);
    if (hasUsableApiKey(existing)) {
        voiceLog("debug", "auth.connectCloudCredential", "existing_credential_found", { providerId, authId });
        const update = await host.confirm({
            title: credentialTitle(providerId),
            message: `${credentialLabel(providerId)} credentials are already connected. Update the saved API key?`,
        });
        voiceLog("debug", "auth.connectCloudCredential", "existing_credential_update_decision", {
            providerId,
            update,
