        if (!update)
            return true;
    }
    const apiKey = await host.prompt({
        title: credentialTitle(providerId),
        message: `Enter a ${credentialLabel(providerId)} API key. It will be saved through OpenCode auth storage, not voice config.`,
        secret: true,
    });
    if (apiKey === undefined) {
        voiceLog("info", "auth.connectCloudCredential", "connect_cancelled", {
            providerId,
