    voiceLog("debug", "config.createDefaultVoiceConfig", "create_default_config");
    return {
        version: voiceConfigVersion,
        microphoneId: "default",
        maxDurationSeconds: defaultMaxDurationSeconds,
        showMicrophoneLevel: true,
    };
