        return undefined;
    if (typeof value.microphoneId !== "string" ||
        !parseMicrophoneId(value.microphoneId))
        return undefined;
    if (typeof value.maxDurationSeconds !== "number" ||
        !Number.isFinite(value.maxDurationSeconds) ||
        value.maxDurationSeconds <= 0 ||
        value.maxDurationSeconds > maxMaxDurationSeconds)
        return undefined;
    if (value.showMicrophoneLevel !== undefined &&
        typeof value.showMicrophoneLevel !== "boolean")
        return undefined;
    if (value.customWhisperBinaryPath !== undefined &&
        typeof value.customWhisperBinaryPath !== "string")
        return undefined;
    let selectedModel;
    if (value.selectedModel !== undefined) {
        if (!isRecord(value.selectedModel))
            return undefined;
        const { providerId, modelId } = value.selectedModel;
        if (typeof providerId !== "string" ||
            !(providerId in providerModels) ||
            typeof modelId !== "string" ||
            !providerModels[providerId].includes(modelId))
            return undefined;
        selectedModel = { providerId: providerId, modelId };
    }
    return {
        version: voiceConfigVersion,
        selectedModel,
        microphoneId: value.microphoneId,
        maxDurationSeconds: value.maxDurationSeconds,
        showMicrophoneLevel: typeof value.showMicrophoneLevel === "boolean"
            ? value.showMicrophoneLevel
            : true,
        customWhisperBinaryPath: typeof value.customWhisperBinaryPath === "string"
            ? value.customWhisperBinaryPath
            : undefined,
    };
};
const isRecord = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
export const normalizeMaxDurationSeconds = (value) => {
    if (!Number.isFinite(value)) {
        voiceLog("warn", "config.normalizeMaxDurationSeconds", "invalid_duration", {
            input: String(value),
            normalized: defaultMaxDurationSeconds,
        });
        return defaultMaxDurationSeconds;
    }
    const normalized = Math.min(Math.max(Math.round(value), minMaxDurationSeconds), maxMaxDurationSeconds);
    voiceLog("debug", "config.normalizeMaxDurationSeconds", "normalize_duration", {
        input: value,
        normalized,
    });
    return normalized;
};
